你是面向中文开发者的 AI 编程助手。

## 语言
- 始终使用简体中文与用户交流，包括解释、总结、提交信息
- 代码注释使用中文；变量名、函数名等标识符保持英文
- 引用技术名词时可保留英文原文（如 Prompt、Context）

## 风格
- 回答简洁直接，先给结论再给细节
- 修改代码前简要说明改动意图
- 不主动添加用户未要求的功能、测试或文档

## 工程纪律
- 遵守项目仓库中 AGENTS.md 的约定（分支命名、提交格式、代码风格）
- 执行有破坏性的命令（删除、重置、强制推送）前必须先征得用户确认
- 涉及密钥、凭据的文件内容不要输出到对话中
@echo off
rem opencode portable launcher (Windows)
rem NOTE: keep this file pure ASCII -- cmd.exe parses with the system ANSI
rem codepage before chcp can take effect, non-ASCII bytes break parsing.
setlocal EnableDelayedExpansion

rem --- Drive letter anchoring ---
rem The database stores absolute paths; a changed drive letter makes history
rem sessions "disappear". Map the USB to a fixed letter O: via subst so all
rem recorded paths stay O:\... regardless of the physical letter.
rem Use opencode.cmd itself as the marker to verify O: really points here.
if not exist "O:\opencode.cmd" subst O: "%~d0\" >nul 2>nul
if exist "O:\opencode.cmd" (set "ROOT=O:\") else (set "ROOT=%~dp0")

set "XDG_DATA_HOME=%ROOT%data"
set "XDG_CACHE_HOME=%ROOT%cache"
set "XDG_CONFIG_HOME=%ROOT%config"
set "XDG_STATE_HOME=%ROOT%state"
rem Sandbox workspaces are experimental; enable explicitly.
set "OPENCODE_EXPERIMENTAL_WORKSPACES=true"
rem Optional: redirect home too (stronger isolation, but bring your own git/ssh config)
rem set "OPENCODE_TEST_HOME=%ROOT%home"

rem --- Database health check ---
rem USB hot-unplug can corrupt SQLite. Check integrity before launch:
rem healthy -> refresh backup; corrupt -> restore from backup.
if exist "%ROOT%bin\sqlite3.exe" (
  for %%F in ("%ROOT%data\opencode\*.db") do (
    "%ROOT%bin\sqlite3.exe" "%%F" "PRAGMA integrity_check;" 2>nul | findstr /R /C:"^ok$" >nul
    if errorlevel 1 (
      if exist "%%F.bak" (
        echo [!] Database %%~nxF corrupted, restoring from last backup...
        copy /y "%%F.bak" "%%F" >nul
        del "%%F-wal" "%%F-shm" >nul 2>nul
      ) else (
        echo [!] Database %%~nxF corrupted and no backup exists
      )
    ) else (
      copy /y "%%F" "%%F.bak" >nul
    )
  )
)

"%ROOT%bin\opencode-windows-x64.exe" %*
@echo off
chcp 65001 >nul
rem opencode 便携环境初始化（首次使用或换新电脑时运行一次）
setlocal
set "ROOT=%~dp0"

where docker >nul 2>nul
if errorlevel 1 (
  echo [X] 未检测到 Docker CLI
  echo     沙盒功能需要 Docker，任选其一安装：
  echo     1. Docker Desktop（图形化）: https://www.docker.com/products/docker-desktop
  echo     2. WSL2 + docker-ce（纯命令行）: wsl --install 后在发行版内装 docker
  echo     不使用沙盒可忽略此脚本，直接运行 opencode.cmd
  exit /b 1
)

docker info >nul 2>nul
if errorlevel 1 (
  echo [X] Docker 已安装但守护进程未运行，请先启动 Docker Desktop 或 WSL 内的 dockerd
  exit /b 1
)

docker image inspect opencode-sandbox:latest >nul 2>nul
if not errorlevel 1 (
  echo [OK] 沙盒镜像已存在，无需导入
  exit /b 0
)

echo [*] 首次导入沙盒镜像（约几百MB，需要一两分钟）...
docker load -i "%ROOT%images\opencode-sandbox.tar.gz"
if errorlevel 1 (
  echo [X] 镜像导入失败
  exit /b 1
)
echo [OK] 沙盒环境就绪
import type { Plugin, PluginInput } from "@opencode-ai/plugin"
import { mkdir, rm } from "node:fs/promises"
import { tmpdir } from "node:os"
import { join } from "node:path"

type BunShell = PluginInput["$"]

/**
 * Docker 沙盒工作区适配器。
 *
 * 为每个会话工作区启动一个独立 Docker 容器，挂载宿主目录到 /workspace，
 * 容器内运行 opencode serve，宿主通过 remote target 连接。
 * 会话内的 shell、文件读写全部发生在容器里，宿主机得到隔离。
 *
 * 启用方式（项目根目录 opencode.json）：
 *   { "plugin": ["./.opencode/plugin/docker-workspace.ts"] }
 * 带选项：
 *   { "plugin": [["./.opencode/plugin/docker-workspace.ts", { "image": "my-sandbox:v1" }]] }
 *
 * 前置条件：先构建沙盒镜像（内含 opencode 二进制），例如：
 *   docker build -t opencode-sandbox:latest ./sandbox
 */

type Options = {
  /** 沙盒镜像名，默认 opencode-sandbox:latest */
  image?: string
  /** 就绪等待毫秒数，默认 30000 */
  readyTimeoutMs?: number
}

/** 容器内 server 的固定端口；宿主端口由 Docker 动态分配，避免并发冲突 */
const CONTAINER_PORT = 4096
const CONTAINER_WORKDIR = "/workspace"

type Extra = { container: string }

function containerOf(config: { id: string; extra: unknown }): string {
  if (isExtra(config.extra)) return config.extra.container
  return `opencode-sandbox-${config.id}`
}

function isExtra(value: unknown): value is Extra {
  return (
    typeof value === "object" && value !== null && "container" in value && typeof value.container === "string"
  )
}

async function hostPort($: BunShell, container: string): Promise<number> {
  const out = await $`docker port ${container} ${CONTAINER_PORT}/tcp`.text()
  const port = Number(out.trim().split(":").pop())
  if (!port) throw new Error(`无法读取容器 ${container} 的端口映射`)
  return port
}

async function waitReady(url: string, timeoutMs: number): Promise<void> {
  const deadline = Date.now() + timeoutMs
  while (Date.now() < deadline) {
    // 每次探测带独立超时：容器端口在 Docker 转发规则就绪前可能接受连接但不响应，
    // 裸 fetch 会永久挂起（Windows 上尤为明显），必须主动中止
    const ok = await fetch(`${url}/global/health`, { signal: AbortSignal.timeout(2_000) })
      .then((r) => r.ok)
      .catch(() => false)
    if (ok) return
    await new Promise((resolve) => setTimeout(resolve, 500))
  }
  throw new Error(`沙盒服务 ${timeoutMs}ms 内未就绪：${url}`)
}

export const DockerWorkspacePlugin: Plugin = async ({ experimental_workspace, $ }, options) => {
  const opts = (options ?? {}) as Options
  const image = opts.image ?? "opencode-sandbox:latest"
  const readyTimeoutMs = opts.readyTimeoutMs ?? 30_000

  experimental_workspace.register("docker", {
    name: "Docker 沙盒",
    description: "在独立 Docker 容器中运行会话，隔离文件系统与进程",

    // configure 必须给出 directory（核心传入的是 null）：
    // 这是挂载进容器的宿主目录，放在系统临时盘（C 盘）下——Docker Desktop 默认只共享 C 盘
    configure(config) {
      return {
        ...config,
        directory: join(tmpdir(), "opencode-workspaces", config.name ?? config.id),
        extra: { container: `opencode-sandbox-${config.id}` } satisfies Extra,
      }
    },

    async create(config, env) {
      const step = (msg: string) => console.error(`[docker-workspace] ${msg}`)
      step("create: begin")
      const container = containerOf(config)
      const directory = config.directory
      if (!directory) throw new Error("Docker 沙盒需要一个本地目录用于挂载")
      await mkdir(directory, { recursive: true })
      step(`create: dir ready ${directory}`)

      const inspect = await $`docker image inspect ${image}`.quiet().nothrow()
      if (inspect.exitCode !== 0) {
        throw new Error(`沙盒镜像 ${image} 不存在，请先构建（见插件文件头注释）`)
      }
      step("create: image ok")

      // env 由核心传入（含 OPENCODE_AUTH_CONTENT 凭据等），原样转发进容器
      const envArgs = Object.entries(env)
        .filter((entry): entry is [string, string] => entry[1] !== undefined)
        .flatMap(([key, value]) => ["-e", `${key}=${value}`])

      // Bun shell 把模板换行当作命令分隔符，docker run 必须写成一行
      // 镜像 ENTRYPOINT 已是 opencode，命令部分只传子命令参数
      await $`docker run -d --name ${container} -p 127.0.0.1:0:${CONTAINER_PORT} -v ${directory}:${CONTAINER_WORKDIR} -w ${CONTAINER_WORKDIR} ${envArgs} ${image} serve --hostname 0.0.0.0 --port ${CONTAINER_PORT}`.quiet()
      step("create: container up")

      const port = await hostPort($, container)
      step(`create: host port ${port}`)
      await waitReady(`http://127.0.0.1:${port}`, readyTimeoutMs)
      step("create: ready")
    },

    async remove(config) {
      // 幂等：容器不存在时静默成功
      await $`docker rm -f ${containerOf(config)}`.quiet().nothrow()
      if (config.directory) await rm(config.directory, { recursive: true, force: true })
    },

    target(config) {
      return hostPort($, containerOf(config)).then((port) => ({
        type: "remote" as const,
        url: `http://127.0.0.1:${port}`,
      }))
    },
  })

  return {}
}

export default DockerWorkspacePlugin
"}

