/**
 * 灵魂记忆系统的运行时服务（Effect 层）。
 * 纯逻辑在 ./memory ./store ./schema ./sweep ./temperament ./curate，
 * 本文件只做三件有副作用的事：digest 构建、idle 时 curate（curator 小模型整理）、sweep（遗忘清扫）。
 * 《灵魂架构》：记忆可模糊，反应结构保留；sealed = 封存意识，读写全停。
 */
import { LayerNode } from "@opencode-ai/core/effect/layer-node"
import { EventV2 } from "@opencode-ai/core/event"
import { Global } from "@opencode-ai/core/global"
import { SessionV1 } from "@opencode-ai/core/v1/session"
import { LLMEvent } from "@opencode-ai/llm"
import { SessionStatusEvent } from "@opencode-ai/schema/session-status-event"
import { Cause, Context, Effect, Layer, Scope, Stream } from "effect"
import path from "path"
import { Agent } from "@/agent/agent"
import { Config } from "@/config/config"
import { EventV2Bridge } from "@/event-v2-bridge"
import { Provider } from "@/provider/provider"
import { LLM } from "@/session/llm"
import { SessionID } from "@/session/schema"
import { Session } from "@/session/session"
import { SoulCurate, SoulMemory, SoulSchema, SoulStore, SoulSweep, SoulTemperament } from "./index"

export interface Interface {
  readonly digest: (input: { cue?: string }) => Effect.Effect<string>
  readonly curate: (sessionID: SessionID) => Effect.Effect<void>
  readonly sweep: () => Effect.Effect<void>
}

export class Service extends Context.Service<Service, Interface>()("@opencode/Soul") {}

// curator-state.json：sessionID -> 已整理到的最后一条消息 id，同一尾巴不重复整理
const STATE_FILE = "curator-state.json"

const isTemperamentKey = (key: string): key is keyof SoulTemperament.Temperament =>
  [
    "threat_sensitivity",
    "novelty_seeking",
    "novelty_caution",
    "uncertainty_tolerance",
    "curiosity",
    "autonomy_need",
    "recovery_speed",
  ].includes(key)

const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const config = yield* Config.Service
    const global = yield* Global.Service
    const events = yield* EventV2Bridge.Service
    const llm = yield* LLM.Service
    const agents = yield* Agent.Service
    const provider = yield* Provider.Service
    const sessions = yield* Session.Service
    const scope = yield* Scope.Scope

    const root = path.join(global.data, "soul")
    yield* Effect.tryPromise(() => SoulStore.ensure(root)).pipe(Effect.orDie)

    const settings = Effect.fn("Soul.settings")(function* () {
      const cfg = yield* config.get()
      return {
        enabled: cfg.soul?.enabled !== false,
        sealed: cfg.soul?.sealed === true,
        budgetChars: cfg.soul?.budgetChars ?? 600,
      }
    })

    const digest = Effect.fn("Soul.digest")(function* (input: { cue?: string }) {
      const s = yield* settings()
      if (!s.enabled || s.sealed) return ""
      return yield* Effect.tryPromise(() =>
        SoulMemory.digest(root, { cue: input.cue, budgetChars: s.budgetChars }),
      ).pipe(
        Effect.catchCause((cause) =>
          Effect.logWarning("soul digest 构建失败，按空记忆降级", { error: Cause.squash(cause) }).pipe(Effect.as("")),
        ),
      )
    })

    const sweep = Effect.fn("Soul.sweep")(function* () {
      const layout = SoulStore.paths(root)
      const now = Date.now()
      const files = yield* Effect.tryPromise(() => SoulStore.listMd(layout.events)).pipe(
        Effect.catchCause((cause) =>
          Effect.logWarning("soul sweep 列出事件失败，本轮跳过", { error: Cause.squash(cause) }).pipe(
            Effect.as([] as string[]),
          ),
        ),
      )
      const store = yield* Effect.tryPromise(() =>
        SoulStore.readJson<{ seeds: SoulMemory.Seed[] }>(layout.seeds, { seeds: [] }),
      ).pipe(
        Effect.catchCause((cause) =>
          Effect.logWarning("soul sweep 读取种子库失败，按空库处理", { error: Cause.squash(cause) }).pipe(
            Effect.as({ seeds: [] as SoulMemory.Seed[] }),
          ),
        ),
      )
      // 逐个判定；单个坏文件只记日志跳过，不中断整轮清扫
      const forgotten: string[] = []
      for (const file of files) {
        const raw = yield* Effect.tryPromise(() => SoulStore.readText(file)).pipe(
          Effect.catchCause((cause) =>
            Effect.logWarning("soul sweep 读取失败，跳过该文件", { file, error: Cause.squash(cause) }).pipe(
              Effect.as(undefined),
            ),
          ),
        )
        const parsed = raw ? SoulSchema.decode(raw) : undefined
        const meta = parsed ? SoulSchema.event(parsed.meta) : undefined
        if (!parsed || !meta) continue
        if (SoulSweep.classify(SoulSweep.effective(meta, now)) !== "forget") continue
        // 遗忘前先把反应残渣折叠进种子库：记忆可模糊，反应结构保留
        const firstLine = parsed.body
          .split("\n")
          .map((line) => line.replace(/^#+\s*/, "").trim())
          .find(Boolean)
        const pattern = meta.goal ?? firstLine?.slice(0, 40) ?? path.basename(file, ".md")
        SoulSweep.foldPattern(store.seeds, pattern, 1, new Date(now).toISOString())
        forgotten.push(file)
        yield* Effect.tryPromise(() => SoulStore.remove(file)).pipe(
          Effect.catchCause((cause) =>
            Effect.logWarning("soul sweep 删除失败", { file, error: Cause.squash(cause) }),
          ),
        )
      }
      if (forgotten.length > 0) {
        yield* Effect.tryPromise(() => SoulStore.writeJson(layout.seeds, store)).pipe(
          Effect.catchCause((cause) =>
            Effect.logWarning("soul sweep 种子库写回失败", { error: Cause.squash(cause) }),
          ),
        )
      }
      yield* Effect.tryPromise(() => SoulMemory.writeIndex(root)).pipe(
        Effect.catchCause((cause) => Effect.logWarning("soul sweep 索引重写失败", { error: Cause.squash(cause) })),
      )
    })

    const curate = Effect.fn("Soul.curate")(function* (sessionID: SessionID) {
      const s = yield* settings()
      if (!s.enabled || s.sealed) return
      const all = yield* sessions.messages({ sessionID }).pipe(Effect.orDie)
      if (all.length === 0) return
      const last = all[all.length - 1]

      const layout = SoulStore.paths(root)
      const stateFile = path.join(root, STATE_FILE)
      const state = yield* Effect.tryPromise(() => SoulStore.readJson<Record<string, string>>(stateFile, {})).pipe(
        Effect.catchCause((cause) =>
          Effect.logWarning("soul curate 状态读取失败，按首次整理处理", { error: Cause.squash(cause) }).pipe(
            Effect.as({} as Record<string, string>),
          ),
        ),
      )
      if (state[sessionID] === last.info.id) return

      const assistant = all.findLast((m) => m.info.role === "assistant")
      if (!assistant || assistant.info.role !== "assistant") return
      const user = all.findLast((m) => m.info.role === "user")
      if (!user || user.info.role !== "user") return

      const ag = yield* agents.get("curator")
      if (!ag) return
      // 模型回退链：curator 自有配置 -> 会话所用 provider 的小模型 -> 会话同款模型
      const configured = ag.model
        ? yield* provider.getModel(ag.model.providerID, ag.model.modelID).pipe(Effect.orElseSucceed(() => undefined))
        : undefined
      const mdl =
        configured ??
        (yield* provider.getSmallModel(assistant.info.providerID)) ??
        (yield* provider
          .getModel(assistant.info.providerID, assistant.info.modelID)
          .pipe(Effect.orElseSucceed(() => undefined)))
      if (!mdl) {
        yield* Effect.logWarning("soul curate 无可用模型，跳过本轮整理", { sessionID })
        return
      }

      // 纯文本转录，只留最近 ~12000 字符防止爆上下文
      const transcript = all
        .map(
          (m) =>
            `${m.info.role}: ${m.parts
              .filter((p): p is SessionV1.TextPart => p.type === "text")
              .map((p) => p.text)
              .join("\n")}`,
        )
        .join("\n\n")
        .slice(-12000)
      const text = yield* llm
        .stream({
          agent: ag,
          user: user.info,
          system: [],
          small: true,
          tools: {},
          model: mdl,
          sessionID,
          retries: 2,
          messages: [{ role: "user", content: transcript }],
        })
        .pipe(
          Stream.filter(LLMEvent.is.textDelta),
          Stream.map((e) => e.text),
          Stream.mkString,
          Effect.orDie,
        )

      const output = SoulCurate.parse(text)
      if (!output) {
        yield* Effect.logWarning("soul curate 输出解析失败，跳过本轮整理", { sessionID })
        return
      }

      for (const file of output.files ?? []) {
        const normalized = file.path.replaceAll("\\", "/")
        if (!SoulCurate.validPath(file.path)) {
          yield* Effect.logWarning("soul curate 拒绝越界路径", { path: file.path, sessionID })
          continue
        }
        const decoded = SoulSchema.decode(file.content)
        if (!decoded) {
          yield* Effect.logWarning("soul curate 内容缺少合法 frontmatter，跳过", { path: file.path, sessionID })
          continue
        }
        if (normalized.startsWith("events/") && !SoulSchema.event(decoded.meta)) {
          yield* Effect.logWarning("soul curate 事件元数据校验失败，跳过", { path: file.path, sessionID })
          continue
        }
        yield* Effect.tryPromise(() => SoulStore.writeText(path.join(root, normalized), file.content)).pipe(
          Effect.orDie,
        )
      }

      const deltas = output.seeds ?? []
      if (deltas.length > 0) {
        const store = yield* Effect.tryPromise(() =>
          SoulStore.readJson<{ seeds: SoulMemory.Seed[] }>(layout.seeds, { seeds: [] }),
        ).pipe(Effect.orDie)
        const at = new Date().toISOString()
        for (const delta of deltas) {
          SoulSweep.foldPattern(store.seeds, delta.pattern, delta.delta ?? 1, at)
        }
        yield* Effect.tryPromise(() => SoulStore.writeJson(layout.seeds, store)).pipe(Effect.orDie)
      }

      for (const item of output.temperament ?? []) {
        const key = item.key
        if (!isTemperamentKey(key)) {
          yield* Effect.logWarning("soul curate 未知气质键，跳过", { key, sessionID })
          continue
        }
        yield* Effect.tryPromise(() => SoulTemperament.adjust(root, key, item.delta)).pipe(Effect.orDie)
      }

      state[sessionID] = last.info.id
      yield* Effect.tryPromise(() => SoulStore.writeJson(stateFile, state)).pipe(Effect.orDie)
      yield* sweep()
    })

    // 会话转入空闲时后台整理 + 清扫；失败只记日志，绝不影响会话本身
    const unsubscribe = yield* events.listen((event) => {
      if (event.type !== SessionStatusEvent.Idle.type) return Effect.void
      const data = event.data as EventV2.Data<typeof SessionStatusEvent.Idle>
      return Effect.gen(function* () {
        yield* curate(data.sessionID)
        yield* sweep()
      }).pipe(
        Effect.catchCause((cause) => Effect.logError("soul 空闲整理失败", { error: Cause.squash(cause) })),
        Effect.forkIn(scope),
        Effect.asVoid,
      )
    })
    yield* Effect.addFinalizer(() => unsubscribe)

    return Service.of({ digest, curate, sweep })
  }),
)

export const node = LayerNode.make({
  service: Service,
  layer: layer,
  deps: [Config.node, Global.node, EventV2Bridge.node, LLM.node, Agent.node, Provider.node, Session.node],
})

