/**
 * 灵魂知识库的文件存储。
 * U 盘场景约束：写操作全部原子化（tmp+rename），JSON 写入前留 .bak，
 * 主文件损坏时自动回退备份——拔盘瞬间写坏只丢一次变更，不丢整个库。
 */
import { mkdir, readdir, readFile, rename, copyFile, rm, writeFile } from "node:fs/promises"
import { join } from "node:path"

export const paths = (root: string) => ({
  people: join(root, "people"),
  events: join(root, "events"),
  facts: join(root, "facts"),
  seeds: join(root, "seeds.json"),
  temperament: join(root, "temperament.json"),
  index: join(root, "MEMORY.md"),
})

export async function ensure(root: string): Promise<void> {
  const layout = paths(root)
  await mkdir(layout.people, { recursive: true })
  await mkdir(layout.events, { recursive: true })
  await mkdir(layout.facts, { recursive: true })
}

export async function readJson<T>(file: string, fallback: T): Promise<T> {
  const main = await readFile(file, "utf8")
    .then((raw) => JSON.parse(raw) as T)
    .catch(() => undefined)
  if (main !== undefined) return main
  return readFile(`${file}.bak`, "utf8")
    .then((raw) => JSON.parse(raw) as T)
