// 提示词注入用：预算硬顶，超出按优先级截断
export async function digest(root: string, opts: { cue?: string; budgetChars?: number } = {}): Promise<string> {
  const budget = opts.budgetChars ?? 600
  const { active, dormant } = await build(root, opts)
  if (active.length === 0 && dormant.length === 0) return ""

  const header = `# 星杳的记忆\n灵魂知识库位于 ${root}，沉睡记忆可用 Grep 唤醒细节。`
  const lines: string[] = []
  let size = header.length
  for (const line of [...active, ...(dormant.length > 0 ? ["## 沉睡", ...dormant] : [])]) {
    if (size + line.length > budget) break
    lines.push(line)
    size += line.length + 1
  }
  const activeBlock = active.length > 0 ? "## 活跃" : ""
  return [header, activeBlock, ...lines].filter(Boolean).join("\n")
}

