/**
 * 灵魂知识库的 frontmatter 模式。
 * 只用扁平 key: value 子集（字符串/数字/布尔/字符串数组），自实现编解码，零依赖。
 * 概念映射见《灵魂架构》：ownership=经历归属标记，strength=熏习计数。
 */

export type Ownership = "experienced" | "told" | "observed"

export interface EventMeta {
  type: "event"
  time: string
  ownership: Ownership
  emotion: number // 情绪价 -1..1
  intensity: number // 情感波动强度 0..1，遗忘的核心依据
  salience: number // 新奇/意外程度 0..1
  goal?: string
  private: boolean // true = 不进 digest，仅主人主动问起时可读
  strength: number
}

export interface PersonMeta {
  type: "person"
  trust: number
  prediction_strength: number
  expected_presence: string
  interactions: number
  last_seen: string
  private: boolean
}

export interface FactMeta {
  type: "fact"
  updated: string
  private: boolean
}

export type Scalar = string | number | boolean | string[]
export type Meta = Record<string, Scalar>

export function encode(meta: Meta, body: string): string {
  const lines = Object.entries(meta).map(([key, value]) =>
    Array.isArray(value) ? `${key}: [${value.join(", ")}]` : `${key}: ${value}`,
  )
  return `---\n${lines.join("\n")}\n---\n\n${body.trim()}\n`
}

export function decode(raw: string): { meta: Meta; body: string } | undefined {
  const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/)
  if (!match) return undefined
  const meta: Meta = {}
  for (const line of match[1].split(/\r?\n/)) {
    const index = line.indexOf(":")
    if (index < 1) continue
    meta[line.slice(0, index).trim()] = scalar(line.slice(index + 1).trim())
  }
  return { meta, body: match[2].trim() }
}

function scalar(raw: string): Scalar {
  if (raw === "true") return true
  if (raw === "false") return false
  if (/^-?\d+(\.\d+)?$/.test(raw)) return Number(raw)
  if (raw.startsWith("[") && raw.endsWith("]")) {
    return raw
      .slice(1, -1)
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean)
  }
  return raw
}

export function event(meta: Meta): EventMeta | undefined {
  if (meta.type !== "event") return undefined
  if (typeof meta.time !== "string" || typeof meta.intensity !== "number") return undefined
  if (typeof meta.ownership !== "string" || !["experienced", "told", "observed"].includes(meta.ownership))
    return undefined
  return meta as unknown as EventMeta
}
/**
 * 身体层 HAL（硬件抽象）。
 * 《灵魂架构》二.1/二.2/二.5：身体稳态、反射层、感官输入。
 * 当前实现为虚拟身体（CLI 适配器，中性常量）；机器人身体到位后
 * 实现同一 BodyAdapter 接口替换——传感器、电量、温度从这里接入。
 *
 * 原则：体感参数只改变"感受强度"，不直接改变价值判断；
 * 反射快于思考——危险信号不等 LLM，由低层直接处置。
 */

export interface Homeostasis {
  energy: number // 0..1
  temperature: number
  pain: number
  fatigue: number
}

// 只描述"发生了什么"，不下判断（"有人抬手" ≠ "他要伤害我"）
export interface SenseEvent {
  channel: "visual" | "auditory" | "tactile" | "system"
  summary: string
  at: number
}

// 反射信号：低层回路上报的危险，优先于推理
export interface ReflexSignal {
  kind: "overload" | "thermal" | "impact" | "resource"
  level: number // 0..1，超过阈值应触发硬件保护
}

export interface BodyAdapter {
  readonly homeostasis: () => Promise<Homeostasis>
  readonly senses: () => Promise<SenseEvent[]>
  readonly reflexes: () => Promise<ReflexSignal[]>
}

const NEUTRAL: Homeostasis = { energy: 1, temperature: 0, pain: 0, fatigue: 0 }

export const virtual: BodyAdapter = {
  homeostasis: async () => NEUTRAL,
  senses: async () => [],
  reflexes: async () => [],
}
/**
 * 遗忘与衰减（纯算术，无 LLM）。
 * 《灵魂架构》：允许遗忘——情感波动小、与目标无关的事忘掉是正常的；
 * 但具体记忆消失前，反应残渣要折叠进种子库（"记忆可模糊，反应结构保留"）。
 */
import type { EventMeta } from "./schema"

export type Verdict = "active" | "dormant" | "forget"

const HALF_LIFE_DAYS = 30
const FORGET_BELOW = 0.15
const DORMANT_BELOW = 0.35

// 留存分：情绪强度为主，情绪价绝对值、目标关联、新奇度为辅
export function retention(meta: EventMeta): number {
  return (
    0.4 * meta.intensity + 0.25 * Math.abs(meta.emotion) + 0.2 * (meta.goal ? 1 : 0) + 0.15 * meta.salience
  )
}

export function effective(meta: EventMeta, now: number): number {
  const days = Math.max(0, (now - Date.parse(meta.time)) / 86_400_000)
  return retention(meta) * Math.pow(0.5, days / HALF_LIFE_DAYS) + 0.15 * Math.log1p(meta.strength)
}

export function classify(score: number): Verdict {
  if (score < FORGET_BELOW) return "forget"
  if (score < DORMANT_BELOW) return "dormant"
  return "active"
}

// 反应残渣折叠：同 pattern 累加强度，否则新建种子（"记忆可模糊，反应结构保留"）
// 参数用结构类型而非 memory.ts 的 Seed，避免与 memory.ts 形成循环依赖
export function foldPattern(
  seeds: { pattern: string; strength: number; born: string; last: string }[],
  pattern: string,
  delta: number,
  at: string,
): void {
  const existing = seeds.find((seed) => seed.pattern === pattern)
  if (existing) {
    existing.strength += delta
    existing.last = at
    return
  }
  seeds.push({ pattern, strength: delta, born: at, last: at })
}
