import { createMemo, createSignal } from "solid-js"
import { createSimpleContext } from "../context/helper"
import { LOCALES, type Locale, type MessageKey } from "./types"
import en from "./locales/en"
import zhCN from "./locales/zh-CN"

const dictionaries: Record<Locale, unknown> = {
  en,
  "zh-CN": zhCN,
}

/** 解析语言设置：环境变量 OPENCODE_TUI_LOCALE 优先，默认简体中文。 */
function detectLocale(): Locale {
  const env = process.env.OPENCODE_TUI_LOCALE
  if (isLocale(env)) return env
  return "zh-CN"
}

function isLocale(value: string | undefined): value is Locale {
  return value !== undefined && (LOCALES as readonly string[]).includes(value)
}

function lookup(dict: unknown, key: string): string | undefined {
  let cur: unknown = dict
  for (const part of key.split(".")) {
    if (cur === null || typeof cur !== "object") return undefined
    cur = Reflect.get(cur, part) as unknown
  }
  return typeof cur === "string" ? cur : undefined
}

function interpolate(text: string, params?: Record<string, string | number>): string {
  if (!params) return text
  return text.replace(/\{\{(\w+)\}\}/g, (raw, name: string) =>
    params[name] === undefined ? raw : String(params[name]),
  )
}

